import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    static Article lireArticle(String ligne) {
        String[] p = ligne.split(";");
        return new Article(p[0].trim(), Integer.parseInt(p[1].trim()), Integer.parseInt(p[2].trim()));
    }

    static int valeurTotale(ArrayList<Article> liste) {
        int total = 0;
        for (Article a : liste) {
            total += a.valeurStock();
        }
        return total;
    }

    static int aCommander(ArrayList<Article> liste, int seuil) {
        int compte = 0;
        for (Article a : liste) {
            if (a.getStock() < seuil) {
                compte++;
            }
        }
        return compte;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ArrayList<Article> boutique = new ArrayList<>();
        String ligne = sc.nextLine();
        while (!ligne.equals("fin")) {
            boutique.add(lireArticle(ligne));
            ligne = sc.nextLine();
        }
        System.out.println("Valeur : " + valeurTotale(boutique) + " FCFA");
        System.out.println("À commander : " + aCommander(boutique, 5));
    }
}

