import java.util.ArrayList;
import java.util.Scanner;

public class Main {
    static Article lireArticle(String ligne) {
        String[] p = ligne.split(";");
        return new Article(p[0].trim(), Integer.parseInt(p[1].trim()), Integer.parseInt(p[2].trim()));
    }

    static Article chercher(ArrayList<Article> liste, String nom) {
        for (Article a : liste) {
            if (a.getNom().equalsIgnoreCase(nom)) {
                return a;
            }
        }
        return null;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        ArrayList<Article> boutique = new ArrayList<>();
        String ligne = sc.nextLine();
        while (!ligne.equals("ventes")) {
            boutique.add(lireArticle(ligne));
            ligne = sc.nextLine();
        }
        ligne = sc.nextLine();
        while (!ligne.equals("fin")) {
            String[] p = ligne.split(";");
            Article a = chercher(boutique, p[0].trim());
            if (a == null) {
                System.out.println("Inconnu : " + p[0].trim());
            } else {
                try {
                    if (!a.vendre(Integer.parseInt(p[1].trim()))) {
                        System.out.println("Refusé : " + ligne);
                    }
                } catch (NumberFormatException e) {
                    System.out.println("Refusé : " + ligne);
                }
            }
            ligne = sc.nextLine();
        }
        int valeur = 0;
        ArrayList<String> bas = new ArrayList<>();
        for (Article a : boutique) {
            System.out.println(a);
            valeur += a.valeurStock();
            if (a.getStock() < 5) {
                bas.add(a.getNom());
            }
        }
        System.out.println("Valeur : " + valeur + " FCFA");
        System.out.println("À commander : " + (bas.isEmpty() ? "aucun" : String.join(", ", bas)));
    }
}

